// request.getRequestDispatcher("/sciezka").forward(request, response):
// - dzieje sie CALKOWICIE po stronie serwera, w ramach JEDNEGO zadania
// - adres URL w przegladarce klienta SIE NIE ZMIENIA
// - atrybuty ustawione na request PRZED forward() SA WIDOCZNE w celu
//   (to caly czas TEN SAM obiekt HttpServletRequest)

req.setAttribute("wiadomosc", "Dane ustawione PRZED forward()");
RequestDispatcher dispatcher = req.getRequestDispatcher("/forward-target");
dispatcher.forward(req, resp);

// w celu: String wiadomosc = (String) req.getAttribute("wiadomosc");
// - dziala, bo to TEN SAM obiekt request!

// response.sendRedirect(url):
// - serwer odsyla odpowiedz ze statusem 302 (Found) i naglowkiem Location
// - klient wykonuje DRUGIE, oddzielne zadanie HTTP - URL SIE ZMIENIA
// - atrybuty ustawione na pierwszym request PRZEPADAJA (nowy obiekt request)

resp.sendRedirect("/redirect-target");

// java.net.http.HttpClient domyslnie NIE podaza za przekierowaniami
// (polityka NEVER) - trzeba jawnie ustawic:
HttpClient followingClient = HttpClient.newBuilder()
        .followRedirects(HttpClient.Redirect.NORMAL)
        .build();
